// Optional HTTPS server for the built Next app, so camera/scan features work on
// a LAN IP during testing (getUserMedia needs a secure context). Not used in
// production (Vercel/Render terminate TLS). Run:
//   npm run build   # with NEXT_PUBLIC_API_BASE=https://<LAN-IP>:8443/api
//   node server.js
// Certs are generated by scripts/gen-certs.sh into ../certs/.
const fs = require("fs");
const path = require("path");
const https = require("https");
const next = require("next");

const port = Number(process.env.PORT || 3443);
const certDir = process.env.CERT_DIR || path.resolve(__dirname, "..", "certs");
const key = path.join(certDir, "key.pem");
const cert = path.join(certDir, "cert.pem");

if (!fs.existsSync(key) || !fs.existsSync(cert)) {
  console.error(`Missing TLS certs in ${certDir}. Run scripts/gen-certs.sh first.`);
  process.exit(1);
}

const app = next({ dev: false });
const handle = app.getRequestHandler();

app.prepare().then(() => {
  https
    .createServer({ key: fs.readFileSync(key), cert: fs.readFileSync(cert) }, (req, res) => handle(req, res))
    .listen(port, "0.0.0.0", () => console.log(`AgriSetuAI web (HTTPS) on https://0.0.0.0:${port}`));
});
